package com.enterpriseflow.controller;
import com.enterpriseflow.api.ApiResponse; import com.enterpriseflow.service.ProjectKnowledgeService; import com.enterpriseflow.service.WorkspaceService; import com.enterpriseflow.workspace.dto.*; import jakarta.validation.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/projects") public class ProjectController {private final WorkspaceService service; private final ProjectKnowledgeService knowledge; public ProjectController(WorkspaceService s,ProjectKnowledgeService k){service=s;knowledge=k;} @GetMapping public ApiResponse<List<Map<String,Object>>> list(Authentication a){return ApiResponse.success("Projects retrieved.",service.listProjects(a.getName()));} @PostMapping public ApiResponse<Map<String,Object>> create(Authentication a,@Valid @RequestBody ProjectRequest r){return ApiResponse.success("Project created.",service.createProject(a.getName(),r));} @GetMapping("/{id}") public ApiResponse<Map<String,Object>> get(Authentication a,@PathVariable UUID id){return ApiResponse.success("Project retrieved.",service.getProject(a.getName(),id));} @GetMapping("/{id}/knowledge") public ApiResponse<Map<String,Object>> knowledge(Authentication a,@PathVariable UUID id){return ApiResponse.success("Project context retrieved.",knowledge.context(a.getName(),id));} @PostMapping("/{id}/understand") public ApiResponse<Map<String,Object>> understand(Authentication a,@PathVariable UUID id,@RequestBody(required=false) Map<String,String> body){return ApiResponse.success("Project insights generated.",knowledge.understand(a.getName(),id,body==null?null:body.get("question")));} @PutMapping("/{id}") public ApiResponse<Map<String,Object>> update(Authentication a,@PathVariable UUID id,@Valid @RequestBody ProjectRequest r){return ApiResponse.success("Project updated.",service.updateProject(a.getName(),id,r));} @DeleteMapping("/{id}") public ApiResponse<Void> archive(Authentication a,@PathVariable UUID id){service.archiveProject(a.getName(),id);return ApiResponse.success("Project archived.",null);} @PostMapping("/{id}/members/{userId}") public ApiResponse<Map<String,Object>> member(Authentication a,@PathVariable UUID id,@PathVariable UUID userId){return ApiResponse.success("Member added.",service.addMember(a.getName(),id,userId));}}
